function memoize(fn) {
  var cache = {};
  return function (n) {
    if (!(n in cache)) {
      cache[n] = fn(n);
    }
    return cache[n];
  };
}

var calls = 0;
var square = memoize(function (n) {
  calls += 1;
  return n * n;
});
console.log(square(4), square(4), square(5));
console.log("calls: " + calls);
